#ifndef SRC_HPP
#define SRC_HPP

#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <map>
#include <algorithm>
#include <cctype>
#include <stdexcept>

// Basic exception hierarchy
class BasicException {
protected:
    std::string message;
public:
    explicit BasicException(const std::string &msg) : message(msg) {}
    virtual const char *what() const noexcept { return message.c_str(); }
    virtual ~BasicException() = default;
};

class ArgumentException : public BasicException {
public:
    explicit ArgumentException(const std::string &msg) : BasicException(msg) {}
};

class IteratorException : public BasicException {
public:
    explicit IteratorException(const std::string &msg) : BasicException(msg) {}
};

struct Pokemon {
    char name[12]; // up to 10 chars + null
    int id;
    std::vector<std::string> types; // each type string
};

class Pokedex {
private:
    std::string filename;
    // map keeps pokemons sorted by id (ascending)
    std::map<int, Pokemon> data; // key = id
    // helper to split types string by '#'
    static std::vector<std::string> splitTypes(const std::string &s) {
        std::vector<std::string> res;
        std::string cur;
        for (char c : s) {
            if (c == '#') {
                if (!cur.empty()) {
                    res.push_back(cur);
                    cur.clear();
                }
            } else {
                cur.push_back(c);
            }
        }
        if (!cur.empty()) res.push_back(cur);
        return res;
    }
    // validation helpers
    static void validateName(const char *name) {
        if (!name) throw ArgumentException("Argument Error: PM Name Invalid (null)");
        std::string s(name);
        if (s.empty() || s.size() > 10) {
            throw ArgumentException("Argument Error: PM Name Invalid (" + s + ")");
        }
        for (char c : s) {
            if (!std::isalpha(static_cast<unsigned char>(c))) {
                throw ArgumentException("Argument Error: PM Name Invalid (" + s + ")");
            }
        }
    }
    static void validateId(int id) {
        if (id <= 0) {
            throw ArgumentException("Argument Error: PM ID Invalid (" + std::to_string(id) + ")");
        }
    }
    static void validateTypes(const char *types_c) {
        if (!types_c) throw ArgumentException("Argument Error: PM Type Invalid (null)");
        std::string s(types_c);
        auto vec = splitTypes(s);
        if (vec.empty() || vec.size() > 7) {
            throw ArgumentException("Argument Error: PM Type Invalid (" + (vec.empty()? "" : vec[0]) + ")");
        }
        for (const auto &t : vec) {
            if (t.empty() || t.size() > 10) {
                throw ArgumentException("Argument Error: PM Type Invalid (" + t + ")");
            }
            for (char c : t) {
                if (!std::isalpha(static_cast<unsigned char>(c))) {
                    throw ArgumentException("Argument Error: PM Type Invalid (" + t + ")");
                }
            }
        }
    }
    // effectiveness table for the 7 allowed types
    static double typeEffect(const std::string &atk, const std::string &def) {
        // default 1.0
        if (atk == def) return 0.5; // same type is resistant
        // water
        if (atk == "water") {
            if (def == "fire" || def == "ground") return 2.0;
            if (def == "water" || def == "grass" || def == "dragon" || def == "electric") return 0.5;
        }
        // fire
        if (atk == "fire") {
            if (def == "grass") return 2.0;
            if (def == "water" || def == "ground" || def == "dragon" || def == "fire") return 0.5;
        }
        // grass
        if (atk == "grass") {
            if (def == "water" || def == "ground") return 2.0;
            if (def == "fire" || def == "grass" || def == "dragon" || def == "flying") return 0.5;
        }
        // electric
        if (atk == "electric") {
            if (def == "water" || def == "flying") return 2.0;
            if (def == "ground") return 0.0;
            if (def == "electric" || def == "grass" || def == "dragon") return 0.5;
        }
        // ground
        if (atk == "ground") {
            if (def == "fire" || def == "electric") return 2.0;
            if (def == "flying") return 0.0;
            if (def == "grass") return 0.5;
        }
        // flying
        if (atk == "flying") {
            if (def == "grass") return 2.0;
            if (def == "electric" || def == "dragon") return 0.5;
        }
        // dragon
        if (atk == "dragon") {
            if (def == "dragon") return 2.0;
        }
        return 1.0;
    }
    // compute multiplier of a single attack type against a pokemon's type list
    static double computeMultiplier(const std::string &atk, const std::vector<std::string> &defTypes) {
        double mult = 1.0;
        for (const auto &def : defTypes) {
            mult *= typeEffect(atk, def);
        }
        return mult;
    }
    // load and save helpers
    void loadFromFile() {
        std::ifstream fin(filename);
        if (!fin) return; // file may not exist, start empty
        std::string line;
        while (std::getline(fin, line)) {
            if (line.empty()) continue;
            // format: name id types (types separated by '#')
            std::istringstream iss(line);
            std::string name; int id; std::string types_str;
            if (!(iss >> name >> id >> types_str)) continue; // malformed line ignored
            Pokemon p; std::snprintf(p.name, sizeof(p.name), "%s", name.c_str());
            p.id = id;
            p.types = splitTypes(types_str);
            data[id] = std::move(p);
        }
    }
    void saveToFile() const {
        std::ofstream fout(filename, std::ios::trunc);
        for (const auto &kv : data) {
            const Pokemon &p = kv.second;
            fout << p.name << ' ' << p.id << ' ';
            for (size_t i = 0; i < p.types.size(); ++i) {
                if (i) fout << '#';
                fout << p.types[i];
            }
            fout << '\n';
        }
    }
public:
    explicit Pokedex(const char *_fileName) : filename(_fileName) {
        loadFromFile();
    }
    ~Pokedex() {
        saveToFile();
    }
    bool pokeAdd(const char *name, int id, const char *types) {
        try {
            validateName(name);
            validateId(id);
            validateTypes(types);
        } catch (const ArgumentException &e) {
            throw; // propagate as required
        }
        // check duplicates
        if (data.count(id)) return false;
        // ensure name uniqueness
        for (const auto &kv : data) {
            if (std::string(kv.second.name) == std::string(name)) return false;
        }
        Pokemon p; std::snprintf(p.name, sizeof(p.name), "%s", name);
        p.id = id;
        p.types = splitTypes(std::string(types));
        data[id] = std::move(p);
        return true;
    }
    bool pokeDel(int id) {
        auto it = data.find(id);
        if (it == data.end()) return false;
        data.erase(it);
        return true;
    }
    std::string pokeFind(int id) const {
        auto it = data.find(id);
        if (it == data.end()) return "None";
        return std::string(it->second.name);
    }
    std::string typeFind(const char *types_c) const {
        std::vector<std::string> query = splitTypes(std::string(types_c));
        std::vector<std::string> matches;
        for (const auto &kv : data) {
            const Pokemon &p = kv.second;
            bool ok = true;
            for (const auto &qt : query) {
                if (std::find(p.types.begin(), p.types.end(), qt) == p.types.end()) {
                    ok = false; break;
                }
            }
            if (ok) matches.push_back(p.name);
        }
        if (matches.empty()) return "None";
        std::ostringstream oss;
        oss << matches.size() << '\n';
        for (size_t i = 0; i < matches.size(); ++i) {
            if (i) oss << '\n';
            oss << matches[i];
        }
        return oss.str();
    }
    float attack(const char *type_c, int id) const {
        auto it = data.find(id);
        if (it == data.end()) return -1.0f;
        std::string atk(type_c);
        double mult = computeMultiplier(atk, it->second.types);
        return static_cast<float>(mult);
    }
    int catchTry() const {
        if (data.empty()) return 0;
        // owned set of ids
        std::unordered_set<int> owned;
        // start with smallest id
        auto it_start = data.begin();
        owned.insert(it_start->first);
        bool progress = true;
        while (progress) {
            progress = false;
            for (const auto &kv : data) {
                int cand_id = kv.first;
                if (owned.count(cand_id)) continue;
                const Pokemon &cand = kv.second;
                bool capturable = false;
                for (int own_id : owned) {
                    const Pokemon &own = data.at(own_id);
                    for (const std::string &atk_type : own.types) {
                        double mult = computeMultiplier(atk_type, cand.types);
                        if (mult >= 2.0 - 1e-9) { // at least 2x
                            capturable = true; break;
                        }
                    }
                    if (capturable) break;
                }
                if (capturable) {
                    owned.insert(cand_id);
                    progress = true;
                }
            }
        }
        return static_cast<int>(owned.size());
    }
    // iterator definition
    struct iterator {
        using map_iter = std::map<int, Pokemon>::iterator;
        map_iter it;
        iterator() = default;
        explicit iterator(map_iter _it) : it(_it) {}
        iterator &operator++() { ++it; return *this; }
        iterator operator++(int) { iterator tmp = *this; ++it; return tmp; }
        iterator &operator--() { --it; return *this; }
        iterator operator--(int) { iterator tmp = *this; --it; return tmp; }
        iterator &operator=(const iterator &rhs) { it = rhs.it; return *this; }
        bool operator==(const iterator &rhs) const { return it == rhs.it; }
        bool operator!=(const iterator &rhs) const { return it != rhs.it; }
        Pokemon &operator*() const { return const_cast<Pokemon&>(it->second); }
        Pokemon *operator->() const { return const_cast<Pokemon*>(&it->second); }
    };
    iterator begin() { return iterator(data.begin()); }
    iterator end() { return iterator(data.end()); }
};

#endif // SRC_HPP
